<script setup>


import {inject, onMounted, ref} from 'vue'


const props=defineProps({node:Object,apps:Array,users:Array,disabled:Boolean})
const api=inject('api'),hosts=ref([])
onMounted(async()=>{try{hosts.value=await api('api/hosts')}catch{/* User can still see the saved target; validation is server-side. */}})
function verification(mode){props.node.verification={mode,expected_status:200,timeout_seconds:10};if(mode==='manual'){props.node.approvers=props.node.approvers||[];props.node.approval_mode=props.node.approval_mode||'all'}}
function monitor(){props.node.monitor={url:'',warmup_seconds:30,window_seconds:60,min_requests:100,max_error_rate:0.01,max_p95_ms:1000,consecutive:2,timeout_seconds:600}}

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Field,FieldLabel,Input,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><fieldset :disabled="disabled" class="operation-fields"><template v-if="node.kind==='verify'"><div class="fields"><Field ><FieldLabel as="div">验证应用</FieldLabel><OptionPicker v-model="node.service" :options="apps"  :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">验证方式</FieldLabel><OptionPicker :model-value="node.verification?.mode" :options="[{value:'manual',label:'人工验证（独立记录）'},{value:'http',label:'HTTP 自动验证'}]" :style="{width:'100%',maxWidth:'100%'}" @update:model-value="verification"/></Field></div><template v-if="node.verification?.mode==='manual'"><div class="fields"><Field ><FieldLabel as="div">验证人员</FieldLabel><OptionPicker v-model="node.approvers" multiple  :options="users" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">完成规则</FieldLabel><OptionPicker v-model="node.approval_mode" :options="[{value:'all',label:'全部人员通过'},{value:'any',label:'任一人员通过'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field></div><small>必须填写验证记录或证据链接；人工结论不会标记为机器测试证明。</small></template><template v-if="node.verification?.mode==='http'"><Field ><FieldLabel as="div">验证接口</FieldLabel><Input v-model="node.verification.url" placeholder="https://测试服务/交付验证（不要填写密钥）"/></Field><div class="fields"><Field ><FieldLabel as="div">预期 HTTP 状态</FieldLabel><Input v-model.number="node.verification.expected_status" type="number"/></Field><Field ><FieldLabel as="div">超时（秒，1–30）</FieldLabel><Input v-model.number="node.verification.timeout_seconds" type="number"/></Field></div><Accordion class="platform-collapse" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>接口返回约定</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;panel&quot;)))"><p>GET 请求带 service、environment、artifact_digest；响应须返回对应身份和 passed:true。普通 HTTP 200 不等于验证通过。</p><pre>{"service":"应用名","environment":"test","artifact_digest":"sha256:…","passed":true}</pre></AccordionContent></AccordionItem></Accordion></template></template><template v-if="node.kind==='script'&&node.script"><div class="fields"><Field ><FieldLabel as="div">SSH 执行主机</FieldLabel><OptionPicker v-model="node.script.host" :options="hosts.filter(h=>h.user!=='root').map(h=>({value:h.name,label:h.name+' · '+h.environment}))"  :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">超时（秒，1–600）</FieldLabel><Input v-model.number="node.script.timeout_seconds" type="number"/></Field></div><Field ><FieldLabel as="div">脚本内容（随交付单冻结）</FieldLabel><Textarea v-model="node.script.content" placeholder="填写 sh 脚本；不要写入密码或 Token" :rows="({minRows:(7),maxRows:Math.max((7),16)}).minRows||4"/></Field><Field ><FieldLabel as="div">参数（每行一个，通过 $1、$2 读取）</FieldLabel><Textarea :model-value="(node.script.arguments||[]).join('\n')" @update:model-value="node.script.arguments=$event?$event.split('\n'):[]" :rows="({minRows:(2),maxRows:Math.max((2),16)}).minRows||4"/></Field><small>只在当前环境的非 root 主机执行，不在 SAE 宿主机或平台进程执行。超时结果待核对，不自动重试。SAE 发布使用专用 API 节点。</small></template><template v-if="node.kind==='deploy'"><Button v-if="!node.monitor" @click="monitor" variant="ghost" size="default" type="button">启用监控达标自动继续批次</Button><template v-else><div class="fields"><Field class="wide"><FieldLabel as="div">批次指标接口</FieldLabel><Input v-model="node.monitor.url" placeholder="受信任的、能识别当前制品与批次的指标适配接口"/></Field><Field ><FieldLabel as="div">预热（秒）</FieldLabel><Input v-model.number="node.monitor.warmup_seconds" type="number"/></Field><Field ><FieldLabel as="div">观察窗口（秒）</FieldLabel><Input v-model.number="node.monitor.window_seconds" type="number"/></Field><Field ><FieldLabel as="div">最低请求量</FieldLabel><Input v-model.number="node.monitor.min_requests" type="number"/></Field><Field ><FieldLabel as="div">最高错误率（0–1）</FieldLabel><Input v-model.number="node.monitor.max_error_rate" type="number"/></Field><Field ><FieldLabel as="div">最高 P95（毫秒）</FieldLabel><Input v-model.number="node.monitor.max_p95_ms" type="number"/></Field><Field ><FieldLabel as="div">连续达标次数</FieldLabel><Input v-model.number="node.monitor.consecutive" type="number"/></Field><Field ><FieldLabel as="div">观察超时（秒）</FieldLabel><Input v-model.number="node.monitor.timeout_seconds" type="number"/></Field></div><small>须指定单应用并开启环境批次暂停。无数据、身份不符、指标异常均暂停；不会自动回滚 SQL 或配置。指标源尚未对接时不要启用。</small><Button @click="delete node.monitor" variant="ghost" size="default" type="button">改为人工观察</Button></template></template></fieldset></template>
<style scoped>.operation-fields{border:0;margin:10px 0 0;padding:0;min-width:0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:grid;gap:6px;margin-top:10px}.wide{grid-column:1/-1}small{display:block;color:var(--muted-foreground);font-size:.75rem;margin-top:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:700px){.fields{grid-template-columns:1fr}}</style>
